using System;

namespace Astrea;

public class PlayerAndSentinelsExceededPurifyOmenData : OmenData
{
	private const string purifyReceiveThatExceedID = "PurifyReceiveThatExceed";

	[NonSerialized]
	private Action<int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(int exceededPurifyAmount)
		{
			ExceededPurifyAction(exceededPurifyAmount, omenInstance);
		};
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerAndSentinelsExceededPurifyActions.Add(omenAction);
	}

	protected virtual void ExceededPurifyAction(int exceededPurifyAmount, OmenInstance omenInstance)
	{
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerAndSentinelsExceededPurifyActions.Remove(omenAction);
	}

	protected string GetPurifyReceiveThatExceedDescription()
	{
		return base.localizationManager.GetLocalizedString("PurifyReceiveThatExceed");
	}
}
